#include <map>
#include <iostream>

int main() {
    using Map = std::map<int, char>;
    Map m = {{10, 'a'}, {20, 'b'}};

    Map::value_type p1 = {10, 'x'};
    Map::value_type p2 = {20, 'y'};

    // Use value_comp() to compare two full map elements (pairs)
    // based only on their keys.
    Map::value_compare vc = m.value_comp();

    if (vc(p1, p2)) {
        std::cout << "p1 < p2 (based on key)" << std::endl;
    }
    // m.key_comp()(p1, p2); // Error: key_comp() expects Key types
}
